 "content": "def transform(grid):
    g = [row[:] for row in grid]
    h, w = len(g), len(g[0])

    # A horizontal 5-bar repeats the perpendicular color sequence found
    # immediately beyond one of its endpoints across the length of the bar.
    for r in range(h):
        c = 0
        while c < w:
            if g[r][c] != 5:
                c += 1
                continue
            a = c
            while c < w and g[r][c] == 5:
                c += 1
            b = c - 1
            if b - a + 1 < 2:
                continue
            for edge in (a, b):
                for dr in (-1, 1):
                    seq = []
                    rr = r + dr
                    while 0 <= rr < h and g[rr][edge] not in (0, 5):
                        seq.append(g[rr][edge])
                        rr += dr
                    if not seq:
                        continue
                    for cc in range(a, b + 1):
                        for i, val in enumerate(seq, start=1):
                            rr = r + dr * i
                            if 0 <= rr < h and g[rr][cc] != 5:
                                g[rr][cc] = val
                    break

    # A vertical 5-bar repeats an adjacent horizontal color pattern along
    # the bar. The sample may be one row or a multi-row tile at either end.
    for c in range(w):
        r = 0
        while r < h:
            if g[r][c] != 5:
                r += 1
                continue
            a = r
            while r < h and g[r][c] == 5:
                r += 1
            b = r - 1
            if b - a + 1 < 2:
                continue
            for edge in (a, b):
                for dc in (-1, 1):
                    startc = c + dc
                    if not (0 <= startc < w):
                        continue
                    # Gather the contiguous sample block adjacent to this endpoint.
                    rows = []
                    rr = edge
                    step = -1 if edge == b else 1
                    while 0 <= rr < h and g[rr][startc] not in (0, 5):
                        rowpat = []
                        cc = startc
                        while 0 <= cc < w and g[rr][cc] not in (0, 5):
                            rowpat.append(g[rr][cc])
                            cc += dc
                        rows.append(rowpat)
                        rr += step
                    if not rows:
                        continue
                    rows.reverse() if edge == b else None
                    # Orient rows top-to-bottom and repeat the tile along the bar,
                    # aligned to the endpoint where the sample was found.
                    tile = rows
                    th = len(tile)
                    for rr in range(a, b + 1):
                        if edge == b:
                            idx = (rr - (b - th + 1)) % th
                        else:
                            idx = (rr - a) % th
                        rowpat = tile[idx]
                        for i, val in enumerate(rowpat):
                            cc = startc + dc * i
                            if 0 <= cc < w and g[rr][cc] != 5:
                                g[rr][cc] = val
                    break
                else:
                    continue
                break
    return g
